// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 value, uint256 warp, bool extraCall) public {
        vm.assume(value == 10 ether);
        vm.assume(warp >= 2 && warp < 365 days);
        address actor = makeAddr("actor");
        vm.deal(actor, 100 ether);
        vm.warp(1);
        vm.prank(actor);
        (bool ok,) = address(c).call{value: 10 ether}("");
        require(ok, "first call failed");
        uint256 firstTime = block.timestamp;
        vm.warp(firstTime + warp);
        if (extraCall) {
            vm.prank(actor);
            (bool ok2,) = address(c).call{value: 10 ether}("");
            require(ok2, "second call failed");
        }
        assertEq(c.pastBlockTime(), extraCall ? block.timestamp : firstTime);
    }
}
